'use strict'

function identity (value) {
  return value
}

class ArrayParser {
  constructor (source, transform) {
    if (typeof source !== 'string') {
      throw new TypeError('source must be a string')
    }
    this.source = source
    this.transform = transform ?? identity
    this.position = 0
    this.entries = []
    this.recorded = []
    this.dimension = 0
  }

  isEof () {
    return this.position >= this.source.length
  }

  nextCharacter () {
    if (this.isEof()) {
      throw new Error('Unexpected end of input')
    }
    const character = this.source[this.position++]
    if (character === '\\') {
      if (this.isEof()) {
        throw new Error('Unexpected end of input after escape character')
      }
      return {
        value: this.source[this.position++],
        escaped: true
      }
    }
    return {
      value: character,
      escaped: false
    }
  }

  record (character) {
    this.recorded.push(character)
  }

  newEntry (includeEmpty) {
    if (this.recorded.length > 0 || includeEmpty) {
      let entry = this.recorded.join('')
      if (entry === 'NULL' && !includeEmpty) {
        entry = null
      }
      if (entry !== null) {
        entry = this.transform(entry)
      }
      this.entries.push(entry)
      this.recorded = []
    }
  }

  consumeDimensions () {
    if (this.source[0] === '[') {
      while (!this.isEof()) {
        const char = this.nextCharacter()
        if (char.value === '=') break
      }
    }
  }

  parse (nested) {
    let character
    let parser
    let quote = false
    this.consumeDimensions()
    while (!this.isEof()) {
      character = this.nextCharacter()
      if (character.value === '{' && !quote) {
        this.dimension++
        if (this.dimension > 1) {
          parser = new ArrayParser(this.source.slice(this.position - 1), this.transform)
          this.entries.push(parser.parse(true))
          this.position += parser.position - 2
        }
      } else if (character.value === '}' && !quote) {
        this.dimension--
        if (this.dimension < 0) {
          throw new Error('Unexpected closing brace')
        }
        if (this.dimension === 0) {
          this.newEntry()
          if (nested) {
            return this.entries
          }
        }
      } else if (character.value === '"' && !character.escaped) {
        if (quote) this.newEntry(true)
        quote = !quote
      } else if (character.value === ',' && !quote) {
        this.newEntry()
      } else {
        this.record(character.value)
      }
    }
    if (quote) {
      throw new Error('Unterminated quoted string')
    }
    if (this.dimension !== 0) {
      throw new Error('Array dimension not balanced')
    }
    return this.entries
  }
}

exports.parse = function parse (source, transform) {
  if (typeof source !== 'string') {
    throw new TypeError('source must be a string')
  }
  if (transform != null && typeof transform !== 'function') {
    throw new TypeError('transform must be a function')
  }
  return new ArrayParser(source, transform).parse()
}